draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.fillStyle = '#ffd7b9';
  ctx.beginPath();
  ctx.arc(W/2, H/2, 100 + 20 * Math.sin(t), 0, 2 * Math.PI);
  ctx.fill();
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';
  ctx.stroke();
  ctx.beginPath();
  ctx.arc(W/2, H/2, 50 + 10 * Math.cos(t), 0, 2 * Math.PI);
  ctx.stroke();
  ctx.restore();
}
